/bin/bash -lc "python - <<'PY'
from collections import defaultdict
mi=defaultdict(lambda:[1e9]*3); ma=defaultdict(lambda:[-1e9]*3); cnt=defaultdict(int); res=defaultdict(set)
for l in open('inputs/protein.shape.q1.pdb'):
    if l.startswith('ATOM'):
        c=l[21]; xyz=list(map(float,(l[30:38],l[38:46],l[46:54])))
        cnt[c]+=1; res[c].add(int(l[22:26]))
        for i,v in enumerate(xyz):
            if v<mi[c][i]:mi[c][i]=v
            if v>ma[c][i]:ma[c][i]=v
for c in sorted(cnt):
 print(c,cnt[c],len(res[c]),mi[c],ma[c])
PY"

